UPDATE Category SET isActive=1, description='Panel enclosures, junction boxes, filter fans, cooling units and heaters.' WHERE id=(SELECT id FROM Category WHERE (lower(name)=lower('Enclosures & Cooling') OR slug='enclosures-cooling') ORDER BY isActive DESC LIMIT 1) AND (isActive=0 OR description IS NOT 'Panel enclosures, junction boxes, filter fans, cooling units and heaters.');
